get_site_settings.code:
use WebCommander\Sdk\Resources\Settings\SiteSettings\SiteSettings;

$response = SiteSettings::getSiteSettings($client);

$settings = $response->map['site_settings'];
echo $settings['store_details']['company_name'], PHP_EOL;
echo 'palette: ', $settings['brand_kit']['palette_name'], PHP_EOL;
echo 'admin time zone: ', $settings['date_time']['admin']['time_zone'], PHP_EOL;

patch_site_settings.code:
use WebCommander\Sdk\Resources\Settings\SiteSettings\SiteSettings;

$response = SiteSettings::patchSiteSettings($client, [
    'site_settings' => [
        'brand_kit' => ['palette_name' => 'Autumn'],
        'date_time' => ['hide_time_zone' => false],
    ],
]);

$settings = $response->map['site_settings'];
echo $settings['brand_kit']['palette_name'], PHP_EOL;
echo $settings['date_time']['hide_time_zone'] ? 'true' : 'false', PHP_EOL;

get_site_settings_section.code:
use WebCommander\Sdk\Resources\Settings\SiteSettings\SiteSettings;

$response = SiteSettings::getSiteSettingsSection($client, 'brand_kit');

$brandKit = $response->map['brand_kit'];
echo 'palette: ', $brandKit['palette_name'], PHP_EOL;
foreach ($brandKit['colors'] as $role => $color) {
    echo $role, ' ', $color, PHP_EOL;
}
